module bst_solver_8 (input [7:0][15:0] nums, output reg possible); reg [1:0] dp[8][8][2]; always @(*) begin int l, r, s, len, k; for(l=0; l<8; l=l+1) for(r=0; r<8; r=r+1) for(s=0; s<2; s=s+1) dp[l][r][s] = 0; for(l=0; l<8; l=l+1) begin dp[l][l][0] = 1; dp[l][l][1] = 1; end for(len=2; len<=8; len=len+1) for(l=0; l<=7; l=l+1) begin r = l + len - 1; if(r >=8) continue; for(k=l; k<=r; k=k+1) begin int left_ok = 1; if(k > l) left_ok = dp[l][k-1][1]; int right_ok = 1; if(k < r) right_ok = dp[k+1][r][0]; if(left_ok && right_ok) begin dp[l][r][0] = 1; dp[l][r][1] = 1; end end end end end always @(*) begin possible = 0; int k, cond; for(k=0; k<8; k=k+1) begin cond = 1; if(k > 0) cond = cond && dp[0][k-1][1]; if(k <7) cond = cond && dp[k+1][7][0]; if(cond) possible = 1; end end end endmodule